[{"order":1,"type":"heading","text":"Page Object Model (POM) and Page Factory Design Patterns in Automation Testing"},{"order":2,"type":"subheading","text":"Introduction to Page Object Model (POM)"},{"order":3,"type":"paragraph","text":"The Page Object Model (POM) is a design pattern popular in test automation that creates an Object Repository for web UI elements. Under this model, each web page in the application has a corresponding page class. This class finds the WebElements and also contains page methods which perform operations on those elements."},{"order":4,"type":"bullet_point","text":"Improves test maintenance by separating test scripts from page specific code."},{"order":5,"type":"bullet_point","text":"Reduces code duplication by reusing page methods across multiple test scripts."},{"order":6,"type":"bullet_point","text":"Enhances readability making test cases easier to understand and write."},{"order":7,"type":"subheading","text":"Introduction to Page Factory"},{"order":8,"type":"paragraph","text":"Page Factory is an extension built into Selenium WebDriver to support the Page Object Model. It provides an annotation-based approach (@FindBy) to initialize web elements and implements lazy initialization through the PageFactory.initElements() method."},{"order":9,"type":"subheading","text":"Implementing POM with Page Factory in Java"},{"order":10,"type":"paragraph","text":"Below is a practical implementation of a Login Page using the Page Object Model and Page Factory pattern in Selenium Java."},{"order":11,"type":"code","text":"import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.FindBy;
import org.openqa.selenium.support.PageFactory;

public class LoginPage {
    WebDriver driver;

    // Constructor to initialize elements
    public LoginPage(WebDriver driver) {
        this.driver = driver;
        PageFactory.initElements(driver, this);
    }

    // Object Repository using @FindBy annotation
    @FindBy(id = "username")
    private WebElement usernameTxt;

    @FindBy(id = "password")
    private WebElement passwordTxt;

    @FindBy(id = "loginBtn")
    private WebElement loginBtn;

    // Action methods
    public void enterUsername(String user) {
        usernameTxt.sendKeys(user);
    }

    public void enterPassword(String pass) {
        passwordTxt.sendKeys(pass);
    }

    public void clickLogin() {
        loginBtn.click();
    }

    public void loginToApplication(String user, String pass) {
        enterUsername(user);
        enterPassword(pass);
        clickLogin();
    }
}"},{"order":12,"type":"subheading","text":"Using the Page Class in Test Scripts"},{"order":13,"type":"paragraph","text":"Once the page class is structured, test scripts can instantiate the page and execute actions without interacting with raw locator strings directly."},{"order":14,"type":"code","text":"import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.testng.annotations.AfterMethod;
import org.testng.annotations.BeforeMethod;
import org.testng.annotations.Test;

public class LoginTest {
    WebDriver driver;
    LoginPage loginPage;

    @BeforeMethod
    public void setUp() {
        driver = new ChromeDriver();
        driver.manage().window().maximize();
        driver.get("https://example.com/login");
    }

    @Test
    public void testValidLogin() {
        loginPage = new LoginPage(driver);
        loginPage.loginToApplication("testUser", "securePassword123");
    }

    @AfterMethod
    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
    }
}"},{"order":15,"type":"subheading","text":"Best Practices"},{"order":16,"type":"bullet_point","text":"Always declare WebElements as private or protected to enforce encapsulation."},{"order":17,"type":"bullet_point","text":"Do not place assertions inside the page object classes; keep assertions strictly within the test classes."},{"order":18,"type":"bullet_point","text":"Use explicit waits instead of relying solely on Page Factory initialization to avoid stale element reference exceptions."}]
